'use strict';
const C=(r=0,i=0)=>[r,i],add=(a,b)=>C(a[0]+b[0],a[1]+b[1]),mul=(a,b)=>C(a[0]*b[0]-a[1]*b[1],a[0]*b[1]+a[1]*b[0]),scale=(a,s)=>C(a[0]*s,a[1]*s),abs2=a=>a[0]**2+a[1]**2;
const s=Math.SQRT1_2, presets={zero:[C(1),C()],one:[C(),C(1)],plus:[C(s),C(s)],minus:[C(s),C(-s)]}, names={zero:'0',one:'1',plus:'+',minus:'-'};
function gate(v,g){return g==='X'?[v[1],v[0]]:g==='H'?[scale(add(v[0],v[1]),s),scale(add(v[0],scale(v[1],-1)),s)]:v.map(x=>[...x]);}
function product(a,b){return a.flatMap(x=>b.map(y=>mul(x,y)));}
function cnot(v){return [v[0],v[1],v[3],v[2]];}
function bloch(v){const a=v[0],b=v[1];return [2*(a[0]*b[0]+a[1]*b[1]),2*(a[0]*b[1]-a[1]*b[0]),abs2(a)-abs2(b)];}
function clean(x){return Math.abs(x)<1e-9?0:x;}
function num(x){return clean(x).toFixed(3);}
function complex(a){const r=clean(a[0]),i=clean(a[1]);return i===0?num(r):`${num(r)}${i<0?'−':'+'}${num(Math.abs(i))}i`;}
function sphere(r,label){const p=([x,y,z])=>[150+105*(Math.sqrt(3)/2*x-.5*y),142+105*(.25*x+Math.sqrt(3)/4*y-Math.sqrt(3)/2*z)];let eq=[];for(let k=0;k<=80;k++)eq.push(p([Math.cos(k*Math.PI/40),Math.sin(k*Math.PI/40),0]).join(','));const q=p(r);let axes='';[[1,0,0],[0,1,0],[0,0,1]].forEach((v,i)=>{const a=p(v.map(x=>-1.18*x)),b=p(v.map(x=>1.18*x));axes+=`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="#b6c8d8"/><text x="${b[0]+5}" y="${b[1]-4}" font-size="18" fill="#526f89">${['x','y','z'][i]}</text>`;});return `<svg class="plot" viewBox="0 0 300 290" role="img" aria-label="${label} 布洛赫向量 ${r.map(num).join(',')}"><circle cx="150" cy="142" r="105" fill="#f6faff" stroke="#9db8ce"/>${axes}<polyline points="${eq.join(' ')}" fill="none" stroke="#bccddd"/><line x1="150" y1="142" x2="${q[0]}" y2="${q[1]}" stroke="#245c9a" stroke-width="4"/><circle cx="${q[0]}" cy="${q[1]}" r="7" fill="#245c9a"/></svg><p class="caption">${label}</p>`;}
function bars(p,labels,color='#3273a6'){let inner='';p.forEach((v,i)=>{const x=55+105*i,h=v*180;inner+=`<rect x="${x}" y="${225-h}" width="54" height="${h}" fill="${color}"/><text x="${x+27}" y="${212-h}" text-anchor="middle" font-size="21" fill="#183855">${Number(num(v))}</text><text x="${x+27}" y="253" text-anchor="middle" font-size="22" fill="#183855">${labels[i]}</text>`;});return `<svg class="plot" viewBox="0 0 470 266" role="img" aria-label="各结果概率 ${p.map(num).join(',')}"><path d="M38 45H454 M38 135H454" fill="none" stroke="#e2eaf1"/><line x1="38" y1="225" x2="454" y2="225" stroke="#8199ad"/><g font-size="15" fill="#60798d" text-anchor="end"><text x="30" y="51">1</text><text x="30" y="141">0.5</text><text x="30" y="231">0</text></g><text x="5" y="19" font-size="16" fill="#60798d">概率</text>${inner}</svg>`;}
function table(v,label=""){return '<table>'+(label?'<caption>'+label+'</caption>':'')+'<tr><th>联合结果</th><th>概率幅（近似）</th><th>概率</th></tr>'+v.map((a,i)=>`<tr><td>${['00','01','10','11'][i]}</td><td>${tex(complex(a))}</td><td>${num(abs2(a))}</td></tr>`).join('')+'</table>';}
function options(){return Object.keys(names).map(k=>`<option value="${k}">${names[k]} 态</option>`).join('');}
const root=document.querySelector('#stage'),mode=document.body.dataset.lab;
function tex(t){return '\\('+t+'\\)';}
let mathSerial=Promise.resolve();function typeset(){if(window.MathJax?.typesetPromise)mathSerial=mathSerial.then(()=>MathJax.typesetPromise()).catch(()=>{});}
function draw(){const ratio=Math.min(innerWidth/1120,innerHeight/630);root.style.transform=`scale(${ratio})`;root.style.marginLeft=`${Math.max(0,(innerWidth-1120*ratio)/2)}px`;}
addEventListener('resize',draw);document.querySelector('#full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{document.querySelector('footer').textContent='当前浏览器未进入原生全屏；可将窗口放大，画面仍会等比缩放。';}};
const controls=document.querySelector('.controls'),body=document.querySelector('.body'),result=document.querySelector('#result');
if(mode==='gates'){
 controls.innerHTML=`<label>输入 <select id="input">${options()}</select></label><label>门 <select id="gate"><option value="H">Hadamard</option><option value="X">X 翻转</option></select></label><button id="apply">先预测，再显示输出</button><button id="hh">固定从0开始：两次 H</button><button id="step" hidden>下一步</button>`;
 let seq=null;function render(show=false){const key=document.querySelector('#input').value,g=document.querySelector('#gate').value,a=presets[key],b=gate(a,g);body.innerHTML=`<div class="panel">${sphere(bloch(a),'输入')}</div><div class="panel">${show?sphere(bloch(b),'输出'):'<p class="summary">先预测输出态。它的0/1概率是否足以说明全部变化？</p>'}</div>`;result.innerHTML=show?`${tex(`${g==='H'?'U_{\\mathrm H}':'X'}|${names[key]}\\rangle`)} 的输出概率幅（依0、1次序）：${tex(`(${num(b[0][0])},\\,${num(b[1][0])})`)}；0/1概率：${num(abs2(b[0]))}、${num(abs2(b[1]))}。`:'';if(show&&g==='X'&&key==='minus')result.innerHTML+=` ${tex('X|-\\rangle=-|-\\rangle')}，整体负号不改变球面点。`;typeset();}
 document.querySelector('#apply').onclick=()=>{seq=null;document.querySelector('#step').hidden=true;render(true);};['input','gate'].forEach(id=>document.querySelector('#'+id).onchange=()=>{seq=null;document.querySelector('#step').hidden=true;render();});
 function sequence(){const states=[presets.zero,presets.plus,presets.zero];body.innerHTML=[0,1,2].map((n)=>`<div class="panel">${n<=seq?sphere(bloch(states[n]),['输入 0','第一次 H 后','第二次 H 后'][n]):'<p class="caption">待施加门</p>'}</div>`).join('');result.innerHTML=tex(['|0\\rangle','|0\\rangle\\xrightarrow{U_{\\mathrm H}}|+\\rangle','|0\\rangle\\xrightarrow{U_{\\mathrm H}}|+\\rangle\\xrightarrow{U_{\\mathrm H}}|0\\rangle'][seq]);document.querySelector('#step').disabled=seq===2;typeset();}
 document.querySelector('#hh').onclick=()=>{seq=0;document.querySelector('#step').hidden=false;sequence();};document.querySelector('#step').onclick=()=>{seq++;sequence();};render();
}
if(mode==='product'||mode==='prepare'||mode==='cnot'){
 const isPrep=mode==='prepare',isLocal=mode==='product';let step=0;
 controls.innerHTML=isPrep?'<button id="next">施加 A 的 Hadamard 门</button><button id="reset">重置为00</button>':`<label>${isLocal?'门前 A：θ':'A：θ'} <input id="theta" type="range" min="0" max="180" value="90" step="1"><span id="tv"></span></label><label>φ <input id="phi" type="range" min="-180" max="180" value="0" step="1"><span id="pv"></span></label><label>${isLocal?'门前 B':'B'} <select id="bin">${options()}</select></label>${isLocal?'<label>A门 <select id="ga"><option>I</option><option>X</option><option>H</option></select></label><label>B门 <select id="gb"><option>I</option><option>X</option><option>H</option></select></label>':'<label><input id="use" type="checkbox" checked>施加 CNOT</label>'}`;
 function render(){let a,b,v,ent=false;if(isPrep){a=step===0?presets.zero:presets.plus;b=presets.zero;v=product(a,b);if(step===2){v=cnot(v);ent=true;}}else{const th=+document.querySelector('#theta').value*Math.PI/180,ph=+document.querySelector('#phi').value*Math.PI/180;a=[C(Math.cos(th/2)),C(Math.sin(th/2)*Math.cos(ph),Math.sin(th/2)*Math.sin(ph))];b=presets[document.querySelector('#bin').value];document.querySelector('#tv').textContent=Math.round(th*180/Math.PI)+'°';document.querySelector('#pv').textContent=Math.round(ph*180/Math.PI)+'°';if(isLocal){a=gate(a,document.querySelector('#ga').value);b=gate(b,document.querySelector('#gb').value);}v=product(a,b);if(!isLocal&&document.querySelector('#use').checked){v=cnot(v);ent=true;}}
 body.innerHTML=`<div class="panel">${ent?bars(v.map(abs2),['00','01','10','11']):`<div class="pair"><div>${sphere(bloch(a),isLocal?'门后 A':'A')}</div><div>${sphere(bloch(b),isLocal?'门后 B':'B')}</div></div>`}<p class="caption">${ent?'输出的联合概率':(isLocal?'局部门后的两个独立纯态':'两个独立纯态的球面点')}</p></div><div class="panel">${table(v,isLocal?'门后联合态':'')}</div>`;
 result.innerHTML=isPrep?tex(['|00\\rangle','|00\\rangle\\xrightarrow{U_{\\mathrm H}\\otimes I}|+\\rangle_A|0\\rangle_B','|00\\rangle\\xrightarrow{U_{\\mathrm H}\\otimes I}|+\\rangle_A|0\\rangle_B\\xrightarrow{U_{\\mathrm{CNOT}}}|\\Phi^+\\rangle=(|00\\rangle+|11\\rangle)/\\sqrt2'][step]):`门前 A 输入：${tex('|\\psi\\rangle_A=\\cos(\\theta/2)|0\\rangle+e^{i\\phi}\\sin(\\theta/2)|1\\rangle')}`;
 if(isPrep){document.querySelector('#next').textContent=['施加 A 的 Hadamard 门','施加 CNOT','已完成'][step];document.querySelector('#next').disabled=step===2;}typeset();}
 if(isPrep){document.querySelector('#next').onclick=()=>{step++;render();};document.querySelector('#reset').onclick=()=>{step=0;render();};}else controls.querySelectorAll('input,select').forEach(el=>el.oninput=render);render();
}
if(mode==='local'){
 controls.innerHTML='<label>A 测量 <select id="axis"><option value="z">z</option><option value="x">x</option><option value="y">y</option></select></label><span>B 固定沿 z；汇总 A 的全部记录</span><button id="sum">查看三轴汇总与球心</button>';
 let summary=false;function render(){const axis=document.querySelector('#axis').value,z=axis==='z',p=z?[.5,0,0,.5]:[.25,.25,.25,.25],labs=z?['00','01','10','11']:['+0','+1','−0','−1'];body.innerHTML=`<div class="panel">${bars(p,labs)}<p class="caption">联合理论概率</p></div><div class="panel">${summary?sphere([0,0,0],'A 的局部坐标'):'<table><tr><th>A 结果</th><th>把 B 两列加起来</th></tr><tr><td>正方向</td><td>'+num(p[0])+' + '+num(p[1])+' = 0.500</td></tr><tr><td>负方向</td><td>'+num(p[2])+' + '+num(p[3])+' = 0.500</td></tr></table>'}</div>`;result.innerHTML=summary?tex('r_x=r_y=r_z=0')+'。球心来自三组测量概率差；整体仍是同一个 Bell 纯态。':`当前只统计 A：两种结果各半；${z?'z 的正、负结果是0、1。':axis+' 的正、负结果用 +、− 表示。'}`;typeset();}
 document.querySelector('#axis').onchange=()=>{summary=false;render();};document.querySelector('#sum').onclick=()=>{summary=!summary;render();};render();
}
if(mode==='compare'){
 controls.innerHTML='<button id="zz">A、B沿 z</button><button id="xx">A、B沿 x</button><label>共同方向 β <input id="angle" type="range" min="0" max="90" step="1" value="0"><span id="angletext">0°</span></label><label>模拟次数 <select id="n"><option>100</option><option>20</option><option>1000</option></select></label><button id="sample">生成模拟记录</button><button id="theory">只看理论</button>';
 let sampled=false;function counts(p,n,seed){let v=[0,0,0,0],x=seed>>>0;for(let k=0;k<n;k++){x=(Math.imul(1664525,x)+1013904223)>>>0;let u=x/4294967296,j=0,sum=p[0];while(u>sum&&j<3)sum+=p[++j];v[j]++;}return v;}
 function render(){const beta=+document.querySelector('#angle').value,b=beta*Math.PI/180,p=[.5,0,0,.5],q=[(1+Math.cos(b)**2)/4,Math.sin(b)**2/4,Math.sin(b)**2/4,(1+Math.cos(b)**2)/4],n=+document.querySelector('#n').value;document.querySelector('#angletext').textContent=beta+'°';const labels=beta===0?['00','01','10','11']:['++','+−','−+','−−'];body.innerHTML='<div class="comparison">'+[p,q].map((v,i)=>{const c=counts(v,n,20261008+i+beta);return `<div><h3>${i?'00/11 硬币混合':'Bell 纯态'}</h3>${bars(v,labels,i?'#718798':'#3273a6')}<p class="small">理论上，A、B的局部布洛赫坐标均为 (0, 0, 0)</p>${sampled?'<p class="small">模拟计数（依次）：'+c.join('、')+'</p>':''}</div>`;}).join('')+'</div>';
 result.innerHTML=beta===0?'A、B沿 z 测量，结果顺序：00、01、10、11。':beta===90?'A、B沿 x 测量，结果顺序：++、+−、−+、−−。':`共同测量方向从 +z 朝 +x 转过 ${beta}°，结果顺序：++、+−、−+、−−。`;
 document.querySelector('footer').textContent=(sampled?'柱高：理论概率；下方：模拟计数。':'柱高：理论概率。')+(beta===0?'':' +、− 分别表示所选方向及其相反方向。');typeset();}
 document.querySelector('#angle').oninput=()=>{sampled=false;render();};document.querySelector('#zz').onclick=()=>{document.querySelector('#angle').value=0;sampled=false;render();};document.querySelector('#xx').onclick=()=>{document.querySelector('#angle').value=90;sampled=false;render();};document.querySelector('#sample').onclick=()=>{sampled=true;render();};document.querySelector('#theory').onclick=()=>{sampled=false;render();};document.querySelector('#n').onchange=render;render();
}
draw();addEventListener('load',typeset);
